// Resolución de la región que usa un comando, según de dónde venga el ajuste.
interface Fuentes {
  lineaDeComandos: string | null;
  entorno: string | null;
  perfil: string | null;
}

export const regionElegida = (fuentes: Fuentes): string | null =>
  fuentes.perfil ?? fuentes.entorno ?? fuentes.lineaDeComandos;

solution.code:
interface Fuentes {
  lineaDeComandos: string | null;
  entorno: string | null;
  perfil: string | null;
}

export const regionElegida = (fuentes: Fuentes): string | null =>
  fuentes.lineaDeComandos ?? fuentes.entorno ?? fuentes.perfil;

spec.code:
assert.strictEqual(
  regionElegida({ lineaDeComandos: null, entorno: "eu-west-1", perfil: "eu-central-1" }),
  "eu-west-1",
);

assert.strictEqual(
  regionElegida({ lineaDeComandos: null, entorno: null, perfil: "eu-central-1" }),
  "eu-central-1",
);

const fuentes = { lineaDeComandos: null, entorno: null, perfil: "eu-central-1" };
regionElegida(fuentes);
assert.deepStrictEqual(fuentes, { lineaDeComandos: null, entorno: null, perfil: "eu-central-1" });
